Tasks implement the EvalTask trait from rho-eval: // In rho-eval/src/tasks.rs struct MyNewTask; impl EvalTask for MyNewTask { fn id(&self) -> &str { "my_new_task" } fn name(&self) -> &str { "My New Task" } fn description(&self) -> &str { "Fix the off-by-one error in the loop." } fn initial_files(&self) -> Vec<(&str, &str)> { vec![("src/lib.rs", "pub fn sum(n: usize) -> usize {
 (0..n).sum()
}
")] } fn user_prompt(&self) -> &str { "Fix the bug in src/lib.rs." } fn verify(&self, files: &[(&str, &str)]) -> TaskOutcome { // Check that the fix is correct let lib = files.iter().find(|(p, _)| *p == "src/lib.rs"); match lib { Some((_, content)) if content.contains("0..=n") => { TaskOutcome::new(self.id(), self.name(), TaskVerdict::Pass, "off-by-one fixed") } Some((_, content)) => { TaskOutcome::new(self.id(), self.name(), TaskVerdict::Fail, format!("unexpected content: {content}")) } None => { TaskOutcome::new(self.id(), self.name(), TaskVerdict::Error, "src/lib.rs not found") } } }
} Register it in all_tasks() and it's automatically available to rho-bench.

